/* ============================================================
   LeoFlash vocabulary deck — ~3000 core English words
   ------------------------------------------------------------
   Words are listed by how frequently they are used in everyday
   English (most useful first). Their CEFR level (A1/A2/B1/B2) is
   derived from that rank by levelOf() below, and is what the app
   groups by. Trivial grammar words (articles, pronouns, auxiliaries)
   are skipped on purpose.

   Row format:  ["word", "part of speech", "Spanish", "simple English definition", "example sentence"]

   The same data, split by level, is exported to data/vocab.<level>.json
   as a project-committed backup — regenerate it with:
       npm run export-levels
   ============================================================ */

// The bands the deck is grouped by: the four CEFR levels plus a thematic
// "Software & IT" track. Keyed by the value stored on each word's `level`.
const LEVELS = {
  a1:       { label: "A1 · Beginner",           icon: "🌱" },
  a2:       { label: "A2 · Elementary",         icon: "🌿" },
  b1:       { label: "B1 · Intermediate",       icon: "🌳" },
  b2:       { label: "B2 · Upper-intermediate", icon: "🌲" },
  software: { label: "Software & IT",           icon: "🧑‍💻" },
};

// CEFR level assigned from each word's frequency rank
// (the most common words are the lowest level).
function levelOf(rank) {
  if (rank <= 500) return "a1";
  if (rank <= 1000) return "a2";
  if (rank <= 2000) return "b1";
  return "b2";
}

